"""Reusable hex socket fit coupon: blind 10 mm sockets, 12 mm height, 0.5 mm entry.

Notch marks bottom-left, sizes ascend left-to-right. For different mechanisms,
change the recipe; this does not claim universal fit-coupon geometry.
"""
from pathlib import Path
import json,math

def coupon_script(target_document,output_path,sizes_mm=(6.55,6.65,6.8)):
    sizes=list(sizes_mm)
    if not 1<=len(sizes)<=10 or any(not math.isfinite(s) or not 2<=s<=10 for s in sizes):
        raise ValueError('Use 1–10 hex sizes, each 2–10 mm across flats.')
    if sizes!=sorted(sizes):raise ValueError('List sizes in ascending order.')
    path=Path(output_path).resolve()
    if path.suffix.lower()!='.3mf':raise ValueError('Coupon output must be 3MF.')
    path.parent.mkdir(parents=True,exist_ok=True)
    c={'target':target_document,'name':target_document+' - fit coupon','output':str(path.parent),'filename':path.name,'sizes':sizes}
    return TEMPLATE.replace('CONFIG_JSON',repr(json.dumps(c)))

TEMPLATE='import adsk.core,adsk.fusion,json,math,time,os\nC=json.loads(CONFIG_JSON)\nOUT=C["output"]\ndef run(_context: str):\n    start=time.perf_counter()\n    if os.path.exists(os.path.join(OUT,C[\'filename\'])):raise RuntimeError(\'Coupon export exists.\')\n    app=adsk.core.Application.get()\n    if app.activeDocument.name!=C[\'target\']:raise RuntimeError(\'Project changed.\')\n    if any(d.name==C[\'name\'] for d in app.documents):raise RuntimeError(\'Coupon document already exists.\')\n    doc=app.documents.add(adsk.core.DocumentTypes.FusionDesignDocumentType)\n    doc.name=C[\'name\']\n    design=adsk.fusion.Design.cast(app.activeProduct)\n    design.unitsManager.distanceDisplayUnits=adsk.fusion.DistanceUnits.MillimeterDistanceUnits\n    root=design.rootComponent\n    point=lambda x,y:adsk.core.Point3D.create(x/10,y/10,0)\n    value=adsk.core.ValueInput.createByString\n    s=root.sketches.add(root.xYConstructionPlane)\n    width=16+14*(len(C["sizes"])-1)\n    outline=[(2,0),(width,0),(width,18),(0,18),(0,2),(2,2)]\n    for a,b in zip(outline,outline[1:]+outline[:1]):s.sketchCurves.sketchLines.addByTwoPoints(point(*a),point(*b))\n    ip=root.features.extrudeFeatures.createInput(s.profiles.item(0),adsk.fusion.FeatureOperations.NewBodyFeatureOperation)\n    if not ip.setOneSideExtent(adsk.fusion.DistanceExtentDefinition.create(value(\'12 mm\')),adsk.fusion.ExtentDirections.PositiveExtentDirection):raise RuntimeError(\'Extent failed.\')\n    f=root.features.extrudeFeatures.add(ip)\n    body=f.bodies.item(0)\n    plane=root.constructionPlanes.createInput()\n    if not plane.setByOffset(root.xYConstructionPlane,value(\'12 mm\')):raise RuntimeError(\'Plane failed.\')\n    top=root.constructionPlanes.add(plane)\n    holes=root.sketches.add(top)\n    sizes=C["sizes"]\n    for x,af in zip([8+14*i for i in range(len(sizes))],sizes):\n        r=af/math.sqrt(3)\n        ps=[(x+r*math.cos(i*math.pi/3),9+r*math.sin(i*math.pi/3)) for i in range(6)]\n        for a,b in zip(ps,ps[1:]+ps[:1]):holes.sketchCurves.sketchLines.addByTwoPoints(point(*a),point(*b))\n    if holes.profiles.count!=len(sizes):raise RuntimeError(\'Coupon profile count wrong.\')\n    collection=adsk.core.ObjectCollection.create()\n    for p in holes.profiles:collection.add(p)\n    ip=root.features.extrudeFeatures.createInput(collection,adsk.fusion.FeatureOperations.CutFeatureOperation)\n    ip.participantBodies=[body]\n    if not ip.setOneSideExtent(adsk.fusion.DistanceExtentDefinition.create(value(\'10 mm\')),adsk.fusion.ExtentDirections.NegativeExtentDirection):raise RuntimeError(\'Cut extent failed.\')\n    root.features.extrudeFeatures.add(ip)\n    expected=(width*18-2*2)*12-sum(math.sqrt(3)/2*af*af*10 for af in sizes)\n    if abs(body.volume*1000-expected)>0.01:raise RuntimeError(\'Coupon volume verification failed.\')\n    edges=adsk.core.ObjectCollection.create()\n    for e in body.edges:\n        b=e.boundingBox\n        if abs(b.minPoint.z-1.2)<1e-6 and abs(b.maxPoint.z-1.2)<1e-6 and any(abs(e.length-af/math.sqrt(3)/10)<1e-6 for af in sizes):edges.add(e)\n    if edges.count!=6*len(sizes):raise RuntimeError(\'Coupon chamfer selection wrong.\')\n    ip=root.features.chamferFeatures.createInput2()\n    if not ip.chamferEdgeSets.addEqualDistanceChamferEdgeSet(edges,value(\'0.5 mm\'),False):raise RuntimeError(\'Chamfer failed.\')\n    root.features.chamferFeatures.add(ip)\n    body=root.bRepBodies.item(0)\n    if not body.isSolid or root.bRepBodies.count!=1:raise RuntimeError(\'Coupon not one solid.\')\n    if any(f.healthState!=adsk.fusion.FeatureHealthStates.HealthyFeatureHealthState for f in root.features):raise RuntimeError(\'Unhealthy coupon feature.\')\n    em=design.exportManager\n    opts=em.createC3MFExportOptions(body,os.path.join(OUT,C[\'filename\']))\n    opts.meshRefinement=adsk.fusion.MeshRefinementSettings.MeshRefinementHigh\n    opts.sendToPrintUtility=False\n    if not em.execute(opts):raise RuntimeError(\'Coupon 3MF export failed.\')\n    # Only this newly created, verified coupon document is discarded.\n    body_volume=body.volume*1000\n    elapsed=time.perf_counter()-start\n    if not doc.close(False):raise RuntimeError(\'Coupon close failed.\')\n    project=next(d for d in app.documents if d.name==C[\'target\'])\n    if not project.activate():raise RuntimeError(\'Project reactivation failed.\')\n    print(json.dumps({\'socket_sizes_across_flats_mm\':sizes,\'size_mm\':[width,18,12], \'volume_mm3\':body_volume,\n        \'orientation\':\'Viewed from above with the 2 mm identification notch at bottom left: sizes run left-to-right in the listed order\',\n        \'solid\':True,\'feature_health_verified\':True,\'fusion_execution_verification_seconds\':elapsed}))\n'
